package tw.rex.parentcontrol;
import android.app.*;import android.os.*;import android.content.*;import android.net.nsd.*;import android.net.wifi.*;import org.json.*;import java.net.*;import java.util.*;import java.util.concurrent.*;import tw.rex.link.*;
public class ParentService extends Service {
 public static volatile ParentService instance;public static volatile String info="尚未啟動";public static final Map<String,Device> devices=new ConcurrentHashMap<String,Device>();
 public static class Device {public String id,name,pub;public volatile long seen;public volatile JSONObject status=new JSONObject();public volatile boolean paired=false;String pending="",pendingSecret="";long pairUntil;String invite="";long inviteUntil;final ArrayDeque<JSONObject> queue=new ArrayDeque<JSONObject>();}
 android.content.SharedPreferences p;ServerSocket server;NsdManager nsd;NsdManager.RegistrationListener reg;WifiManager.MulticastLock multicast;volatile boolean running;ExecutorService pool=Executors.newFixedThreadPool(4);String phoneId;DatagramSocket beacon;
 public void onCreate(){super.onCreate();instance=this;p=getSharedPreferences("parent",0);phoneId=p.getString("phoneId","");if(phoneId.isEmpty()){phoneId=UUID.randomUUID().toString();p.edit().putString("phoneId",phoneId).commit();}foreground();running=true;new Thread(()->listen(),"parent-listener").start();}
 void foreground(){NotificationManager nm=(NotificationManager)getSystemService(NOTIFICATION_SERVICE);if(Build.VERSION.SDK_INT>=26)nm.createNotificationChannel(new NotificationChannel("link","電視連線服務",NotificationManager.IMPORTANCE_LOW));Notification.Builder b=Build.VERSION.SDK_INT>=26?new Notification.Builder(this,"link"):new Notification.Builder(this);b.setContentTitle("邊看邊學家長遙控").setContentText("同網路電視可自動搜尋本手機").setSmallIcon(android.R.drawable.ic_menu_manage).setOngoing(true).setContentIntent(PendingIntent.getActivity(this,0,new Intent(this,ParentActivity.class),PendingIntent.FLAG_IMMUTABLE));startForeground(1,b.build());}
 void listen(){try{server=new ServerSocket(0);info="自動搜尋已啟動 · 埠 "+server.getLocalPort();new Thread(()->beaconLoop(),"parent-discovery").start();try{WifiManager wifi=(WifiManager)getApplicationContext().getSystemService(WIFI_SERVICE);if(wifi!=null){multicast=wifi.createMulticastLock("learning-parent");multicast.setReferenceCounted(false);multicast.acquire();}}catch(Exception ignored){}try{nsd=(NsdManager)getSystemService(NSD_SERVICE);NsdServiceInfo service=new NsdServiceInfo();service.setServiceName("LearningParent-"+phoneId.substring(0,8));service.setServiceType("_learnparent._tcp.");service.setPort(server.getLocalPort());reg=new NsdManager.RegistrationListener(){public void onServiceRegistered(NsdServiceInfo s){info="家長手機可被電視搜尋（雙重搜尋） · 埠 "+server.getLocalPort();}public void onRegistrationFailed(NsdServiceInfo s,int e){info="區網備援搜尋中 · 埠 "+server.getLocalPort();}public void onServiceUnregistered(NsdServiceInfo s){}public void onUnregistrationFailed(NsdServiceInfo s,int e){}};nsd.registerService(service,NsdManager.PROTOCOL_DNS_SD,reg);}catch(Exception error){info="區網備援搜尋中 · 埠 "+server.getLocalPort();}while(running){final Socket s=server.accept();pool.submit(()->{try(Socket socket=s){socket.setSoTimeout(3500);JSONObject req=Wire.read(socket.getInputStream());JSONObject res=handle(req);Wire.write(socket.getOutputStream(),res);}catch(Exception ignored){}});}}catch(Exception e){if(running)info="連線服務錯誤："+e.getClass().getSimpleName()+"，請重新啟動連線服務";}}
 void beaconLoop(){try{beacon=new DatagramSocket(null);beacon.setReuseAddress(true);beacon.bind(new InetSocketAddress(LanDiscovery.PORT));byte[] buffer=new byte[2048];while(running){DatagramPacket packet=new DatagramPacket(buffer,buffer.length);beacon.receive(packet);try{if(!LanDiscovery.privateV4(packet.getAddress()))continue;JSONObject q=new JSONObject(new String(packet.getData(),0,packet.getLength(),"UTF-8"));if(!"learning-find-v1".equals(q.optString("type")))continue;String nonce=q.optString("nonce");if(nonce.length()!=36)continue;JSONObject response=new JSONObject().put("type","learning-parent-v1").put("nonce",nonce).put("phoneId",phoneId).put("port",server.getLocalPort());byte[] bytes=response.toString().getBytes("UTF-8");beacon.send(new DatagramPacket(bytes,bytes.length,packet.getAddress(),packet.getPort()));}catch(Exception ignored){}}}catch(Exception e){if(running)info="區網備援搜尋不可用；請確認同一Wi-Fi或用手動連線";}}
 synchronized JSONObject handle(JSONObject req)throws Exception{String id=req.getString("id");if(!id.matches("[a-zA-Z0-9-]{1,64}"))throw new Exception();Device d=devices.get(id);if(d==null){if(devices.size()>=12)throw new Exception("limit");d=new Device();d.id=id;devices.put(id,d);}JSONObject out=new JSONObject();out.put("phoneId",phoneId);out.put("phoneName",Build.MANUFACTURER+" "+Build.MODEL);out.put("pairVersion",2);
 if(req.optString("type").equals("hello")){String pub=req.getString("pub");if(pub.length()>2048)throw new Exception();d.name=req.optString("name","安卓電視");if(d.pub!=null&&!d.pub.equals(pub)){d.pending="";d.pendingSecret="";d.invite="";}d.pub=pub;String offered=req.optString("invitePhone").equals(phoneId)?req.optString("invite"):"";if(!offered.equals(d.invite)&&!d.invite.isEmpty()){d.pending="";d.pendingSecret="";d.pairUntil=0;}if(!offered.isEmpty()){d.invite=offered;d.inviteUntil=System.currentTimeMillis()+10000;}else{d.invite="";d.inviteUntil=0;}d.seen=System.currentTimeMillis();if(!d.pending.isEmpty()&&System.currentTimeMillis()<d.pairUntil)out.put("pair",d.pending);return out;}
 String secret=p.getString("secret."+id,"");JSONObject data=null;if(!secret.isEmpty())try{data=Crypto.open(secret,req.getString("data"));}catch(Exception ignored){}
 if(data==null&&!d.pendingSecret.isEmpty()&&System.currentTimeMillis()<d.pairUntil){data=Crypto.open(d.pendingSecret,req.getString("data"));secret=d.pendingSecret;p.edit().putString("secret."+id,secret).commit();d.pendingSecret="";d.pending="";}
 if(data==null)throw new Exception("not paired");d.paired=true;d.seen=System.currentTimeMillis();d.name=data.optString("name","電視");d.status=data.optJSONObject("status");String ack=data.optString("ack");synchronized(d.queue){if(!d.queue.isEmpty()&&d.queue.peek().optString("id").equals(ack))d.queue.remove();while(!d.queue.isEmpty()&&System.currentTimeMillis()-d.queue.peek().optLong("issued")>60000)d.queue.remove();JSONObject response=new JSONObject();response.put("nonce",data.getString("nonce"));if(!d.queue.isEmpty())response.put("command",d.queue.peek());out.put("data",Crypto.seal(secret,response));}return out;}
 public synchronized void acceptInvite(String id,String recovery)throws Exception{Device d=devices.get(id);if(d==null||d.invite.isEmpty()||System.currentTimeMillis()>=d.inviteUntil)throw new Exception("邀請已過期，請在電視重新選擇此手機");if(!d.pending.isEmpty()&&!d.pendingSecret.isEmpty()&&System.currentTimeMillis()<d.pairUntil)return;String key=Crypto.token();JSONObject data=new JSONObject().put("invite",d.invite).put("key",key).put("phone",phoneId).put("recovery",Crypto.digest(recovery));d.pending=Crypto.encrypt(d.pub,data);d.pendingSecret=key;d.pairUntil=System.currentTimeMillis()+120000;}
 public synchronized void pair(String id,String code,String recovery)throws Exception{Device d=devices.get(id);if(d==null||d.pub==null)throw new Exception("電視已離線");if(!code.matches("[0-9]{6}"))throw new Exception("請輸入電視顯示的六位數配對碼");String secret=Crypto.token();JSONObject b=new JSONObject();b.put("pin",code);b.put("key",secret);b.put("phone",phoneId);b.put("recovery",Crypto.digest(recovery));d.pending=Crypto.encrypt(d.pub,b);d.pendingSecret=secret;d.pairUntil=System.currentTimeMillis()+120000;}
 public void command(String id,String action,JSONObject payload)throws Exception{Device d=devices.get(id);if(d==null||!d.paired||System.currentTimeMillis()-d.seen>8000)throw new Exception("電視尚未配對或已離線");synchronized(d.queue){if(d.queue.size()>=10)throw new Exception("請等待上一個指令完成");JSONObject c=new JSONObject();c.put("id",UUID.randomUUID().toString());c.put("action",action);c.put("payload",payload);c.put("issued",System.currentTimeMillis());d.queue.add(c);}}
 public int onStartCommand(Intent i,int f,int id){return START_STICKY;}public IBinder onBind(Intent i){return null;}
 public void onDestroy(){running=false;instance=null;if(beacon!=null)beacon.close();try{server.close();}catch(Exception e){}try{nsd.unregisterService(reg);}catch(Exception e){}if(multicast!=null&&multicast.isHeld())multicast.release();pool.shutdownNow();info="已停止";super.onDestroy();}
}
